function migrate(){
 data.facilities??=structuredClone(FACILITIES);data.selectedFacility??='carehome';data.notes??={};
 data.beneficiaries.forEach((b,i)=>{b.facility??=['B-005','B-006','B-007','B-008'].includes(b.id)?'hospital':'carehome';b.room??=b.facility==='carehome'?`Level ${i%2+1} · Room ${201+i}`:`Ward ${i%2+2} · Bay ${String.fromCharCode(65+i%4)}`;});
 data.volunteers.forEach(v=>{v.training??=Object.fromEntries(TRAINING.map(t=>[t,v.status==='Active'||v.id==='V-005']));});
 data.services.forEach(s=>{const b=data.beneficiaries.find(x=>x.name===s.beneficiary);s.facility??=b?.facility||'carehome';s.beneficiaryId??=b?.id;s.language??=b?.language||'English';s.brief??=s.programme==='Digital confidence'?'Help with everyday phone and tablet tasks.':s.programme==='Care companions'?'Provide companionship during an appointment or outing.':'Spend time talking, walking or joining a community activity.';});
 data.hourSubmissions??=[{id:'H-001',volunteerId:'V-001',facility:'carehome',title:'Companionship visit',date:'30 Oct 2026',hours:2,status:'Pending'},{id:'H-002',volunteerId:'V-004',facility:'hospital',title:'Digital support session',date:'31 Oct 2026',hours:1.5,status:'Pending'}];
 data.version=2;
}
