let workspace='nonprofit',page='overview',query='',filter='all',chartMode='hours',calendarList=innerWidth<700,batchDraft=null;
const VIEW_NAMES={nonprofit:'Nonprofit organisation',care:'Care home / hospital',community:'Community'};
const PAGE_LABELS={nonprofit:{overview:'Overview',volunteers:'Volunteer directory',onboarding:'Recruitment & onboarding',training:'Training & readiness',placements:'Partner requests',shifts:'Placements & shifts',hours:'Hours & recognition',reports:'Volunteer reports',settings:'Settings'},care:{overview:'Overview',residents:'Residents & patients',requests:'Service requests',calendar:'Care schedule',followups:'Follow-ups',batch:'Batch intake',reports:'Institution reports',settings:'Settings'},community:{volunteer:'Volunteer experience',elder:'Senior experience',institution:'Institution tools',rewards:'Rewards & certificates',safety:'Safety & feedback',approvals:'Service approvals'}};
const LEGACY={volunteer:['volunteer','explore'],elder:['elder','explore'],institution:['institution','residents'],rewards:['volunteer','rewards'],safety:['volunteer','safety'],approvals:['admin','admin']};
const isCare=()=>workspace==='care';
const facility=()=>data.facilities.find(f=>f.id===data.selectedFacility)||data.facilities[0];
const facilityName=id=>data.facilities.find(f=>f.id===id)?.name||'Care partner';
const residentWord=()=>facility().id==='hospital'?'patient':'resident';
const residents=()=>data.beneficiaries.filter(b=>b.facility===facility().id);
const services=()=>isCare()?data.services.filter(s=>s.facility===facility().id):data.services;
const activeVolunteers=()=>data.volunteers.filter(v=>v.status==='Active');
const waitingHours=()=>data.hourSubmissions.filter(h=>h.status==='Pending');
const totalHours=()=>data.volunteers.reduce((sum,v)=>sum+Number(v.hours),0);
const openRequests=()=>data.services.filter(s=>s.volunteer===UNASSIGNED&&pendingStatus(s));
const pendingVolunteers=()=>data.volunteers.filter(v=>v.status==='Onboarding');
const followups=()=>residents().filter(b=>b.status!=='Active');
const initials=s=>String(s).split(' ').slice(0,2).map(x=>x[0]||'').join('');
const palette=i=>['','blue','pink','purple'][i%4];
const personAvatar=(name,i=0)=>`<span class="avatar ${palette(i)}">${esc(initials(name))}</span>`;
function save(){try{localStorage.setItem(STORAGE,JSON.stringify(data))}catch{toast('Changes are available for this session only.')}}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),4200)}
function button(label,action,ico='',primary=false,attrs=''){return `<button type="${attrs.includes('type="submit"')?'submit':'button'}" class="btn${primary?' primary':''}" data-action="${action}" ${attrs.replace('type="submit"','')}>${ico?icon(ico):''}${label}</button>`}
function textButton(label,action,attrs=''){return `<button type="button" class="text-btn" data-action="${action}" ${attrs}>${label}${icon('arrow')}</button>`}
function badge(status){return `<span class="status ${/due|Needs|intake|Onboarding|Pending|Awaiting/.test(status)?'amber':status==='Cancelled'?'gray':''}">${esc(status)}</span>`}
function heading(eyebrow,title,subtitle,actions=''){return `<div class="page-head"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${subtitle}</p></div><div class="actions">${actions}</div></div>`}
function linkRoute(target,label,ico='arrow'){return `<a class="btn" href="#${target}">${icon(ico)}${label}</a>`}
function parseRoute(){
 const hash=location.hash.slice(1);
 if(hash==='main')return;
 const aliases={overview:'nonprofit/overview',beneficiaries:'care/residents',volunteers:'nonprofit/volunteers',programmes:'nonprofit/placements',calendar:'nonprofit/shifts',funding:'nonprofit/overview',reports:'nonprofit/reports',settings:'nonprofit/settings',community:'community/volunteer',rewards:'community/rewards',safety:'community/safety',approvals:'community/approvals'};
 const target=aliases[hash]||hash||'nonprofit/overview';
 const parts=target.split('/');workspace=PAGE_LABELS[parts[0]]?parts[0]:'nonprofit';page=PAGE_LABELS[workspace][parts[1]]?parts[1]:(workspace==='community'?'volunteer':'overview');
 if(hash!==`${workspace}/${page}`)history.replaceState(null,'',`#${workspace}/${page}`);
}
function go(target){if($('#dialog').open)$('#dialog').close();$('#sidebar').classList.remove('open');query='';filter='all';if(location.hash===`#${target}`){parseRoute();render();return}location.hash=target;}
function contextTabs(){return `<label class="staff-view-label"><span>Switch view</span><select id="perspective" class="perspective-picker" aria-label="Switch view"><option value="volunteer">Individual volunteer</option><option value="nonprofit" ${workspace==='nonprofit'?'selected':''}>Nonprofit organisation</option><option value="elder">Senior</option><option value="care" ${workspace==='care'?'selected':''}>Care home / hospital</option></select></label>`;}
function navItem(key,ico,count=''){return `<a href="#${workspace}/${key}" class="${page===key?'active':''}" ${page===key?'aria-current="page"':''}>${icon(ico)}<span>${PAGE_LABELS[workspace][key]}</span>${count?`<span class="nav-count">${count}</span>`:''}</a>`}
function shell(){
 document.body.dataset.workspace=workspace;document.body.dataset.perspective=workspace==='care'?'institution':'admin';document.querySelector('meta[name="theme-color"]').content=workspace==='care'?'#173f65':'#173f32';
 const title=workspace==='care'?facility().name:workspace==='nonprofit'?data.org:'Silver Link Community';
 const context=workspace==='care'?'Resident & patient support':workspace==='nonprofit'?'Volunteer operations':'Personal service tools';
 const menus=workspace==='nonprofit'?navItem('overview','grid')+navItem('volunteers','people')+navItem('onboarding','clipboard',pendingVolunteers().length||'')+navItem('training','shield')+navItem('placements','building',openRequests().length||'')+navItem('shifts','calendar')+navItem('hours','award',waitingHours().length||'')+navItem('reports','chart'):workspace==='care'?navItem('overview','grid')+navItem('residents','people')+navItem('requests','clipboard')+navItem('calendar','calendar')+navItem('followups','message',followups().length||'')+navItem('batch','layers')+navItem('reports','chart'):Object.keys(LEGACY).map((k,i)=>navItem(k,['heart','people','building','award','shield','clipboard'][i])).join('');
 $('#sidebar').innerHTML=`<a class="brand" href="#${workspace}/${workspace==='community'?'volunteer':'overview'}"><span class="brand-mark">${icon('link')}</span><span><strong>Silver Link</strong><small>银 龄 连 线</small></span></a><button class="mobile-sidebar-close icon-btn" data-action="menu" aria-label="Close navigation">${icon('close')}</button><div class="context-card"><span class="org-icon">${icon(workspace==='nonprofit'?'heart':'building')}</span><div><strong>${esc(title)}</strong><small>${context}</small></div></div><div class="nav-label">${workspace==='nonprofit'?'MANAGE VOLUNTEERS':workspace==='care'?'CARE INSTITUTION':'COMMUNITY TOOLS'}</div><nav class="nav" aria-label="${VIEW_NAMES[workspace]} navigation">${menus}</nav><div class="sidebar-bottom"><div class="community-card">${icon(workspace==='care'?'heart':'leaf')}<strong>${workspace==='nonprofit'?'People make the difference.':workspace==='care'?'Care starts with knowing someone.':'The familiar Silver Link experience.'}</strong><p>${workspace==='nonprofit'?'Help volunteers find their place, grow their skills and give their time.':workspace==='care'?'Bring individual needs, visits and follow-ups into one shared view.':'Requests, matching, rewards and accessible community services.'}</p><a href="#community/${workspace==='care'?'elder':'volunteer'}">${workspace==='care'?'Open senior portal':'Open community tools'} ${icon('arrow')}</a></div>${workspace!=='community'?`<a class="settings-link" href="#${workspace}/settings">${icon('settings')}Workspace settings</a>`:`<a class="settings-link" href="#nonprofit/overview">${icon('grid')}Back to staff workspace</a>`}</div>`;
 $('#topbar').innerHTML=`<div class="topbar-left"><button class="icon-btn mobile-menu" data-action="menu" aria-label="Toggle navigation">${icon('menu')}</button>${contextTabs()}</div><div class="top-actions"><button class="search-trigger" data-action="search" aria-label="Search this workspace">${icon('search')}<span>Search this view</span><span class="key">⌘ K</span></button><button class="demo-info" data-action="about">Demo</button><button class="icon-btn notification" data-action="notifications" aria-label="View updates">${icon('bell')}</button><span class="avatar">${workspace==='care'?'CT':'SL'}</span></div>`;
}
function facilityBar(){return `<div class="facility-bar"><div class="facility-label">${icon('building')}<div><strong>${esc(facility().name)}</strong><span>${facility().type} · ${facility().area}</span></div></div><div class="segment" aria-label="Choose institution"><button data-action="facility" data-id="carehome" class="${facility().id==='carehome'?'selected':''}">Care home</button><button data-action="facility" data-id="hospital" class="${facility().id==='hospital'?'selected':''}">Hospital</button></div></div>`}
function metric(label,value,suffix,ico,note,target){return `<a class="metric" href="#${target}"><div class="metric-top"><span>${label}</span>${icon(ico)}</div><div class="metric-value">${value}<small>${suffix}</small></div><div class="metric-bottom"><span class="metric-caption">${note}</span>${icon('chevron')}</div></a>`}
function nonprofitMetrics(){return `<div class="metrics">${metric('Active volunteers',activeVolunteers().length,'','heart',`${data.volunteers.length} people in your team`,'nonprofit/volunteers')}${metric('Awaiting onboarding',pendingVolunteers().length,'','clipboard','Applications to review','nonprofit/onboarding')}${metric('Upcoming placements',data.services.filter(s=>s.volunteer!==UNASSIGNED&&pendingStatus(s)).length,'','calendar','2–8 November · this week','nonprofit/shifts')}${metric('Verified volunteer hours',totalHours(),'hrs','clock',`${waitingHours().length} submissions to verify`,'nonprofit/hours')}</div>`}
function careMetrics(){return `<div class="metrics">${metric(facility().id==='hospital'?'Patients supported':'Residents supported',residents().length,'','people','Individual needs & preferences','care/residents')}${metric('Open service requests',services().filter(s=>s.volunteer===UNASSIGNED&&pendingStatus(s)).length,'','clipboard','Awaiting volunteer placement','care/requests')}${metric('Scheduled visits',services().filter(s=>s.volunteer!==UNASSIGNED&&pendingStatus(s)).length,'','calendar','2–8 November · this week','care/calendar')}${metric('Follow-ups due',followups().length,'','message','Keep care plans up to date','care/followups')}</div>`}
function table(headers,rows,cls=''){return `<div class="table-wrap"><table class="${cls}"><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows||`<tr><td colspan="${headers.length}" class="empty">Nothing to show yet.</td></tr>`}</tbody></table></div>`}
function panelHead(title,subtitle='',action=''){return `<div class="panel-head"><div><h2>${title}</h2>${subtitle?`<p>${subtitle}</p>`:''}</div>${action}</div>`}
function volunteerChart(){
 const people=data.volunteers.slice(0,6);const values=people.map(v=>chartMode==='hours'?v.hours:data.services.filter(s=>s.volunteer===v.name&&pendingStatus(s)).length);const total=values.reduce((a,b)=>a+b,0);const max=Math.max(...values,1);
 return panelHead('Your team’s contribution',chartMode==='hours'?'Verified hours by volunteer':'Upcoming placements by volunteer',`<div class="segment"><button data-action="chart" data-mode="hours" class="${chartMode==='hours'?'selected':''}">Hours</button><button data-action="chart" data-mode="shifts" class="${chartMode==='shifts'?'selected':''}">Placements</button></div>`)+`<div class="chart-summary"><strong>${total}</strong><span>${chartMode==='hours'?'verified hours':'scheduled placements'} · ${people.length} volunteers shown</span></div><div class="chart" role="img" aria-label="${esc(people.map((v,i)=>`${v.name}: ${values[i]} ${chartMode}`).join('; '))}"><div class="grid-lines">${[max,Math.round(max*2/3),Math.round(max/3),0].map(n=>`<div><span>${n}</span></div>`).join('')}</div><div class="bars">${people.map((v,i)=>`<div class="bar-column ${i===2?'today':''}" title="${esc(v.name)}: ${values[i]}"><div class="bar-stack" style="height:${Math.max(values[i]/max*100,2)}%"><div class="bar-done" style="height:100%"></div></div><label>${esc(v.name.split(' ')[0])}</label></div>`).join('')}</div></div><div class="legend"><span><i class="dot"></i>${chartMode==='hours'?'Approved service hours':'Confirmed volunteer assignments'}</span></div>`;
}
function attentionItem(ico,title,sub,label,action,attrs='',color=''){return `<div class="attention-item"><span class="attention-symbol ${color}">${icon(ico)}</span><div class="attention-copy"><h3>${title}</h3><p>${sub}</p>${textButton(label,action,attrs)}</div></div>`}
function attention(){
 if(isCare())return panelHead('Care team follow-ups','Keep every request moving.')+`<div class="attention-list">${attentionItem('people',`${followups().length} ${followups().length===1?'person needs':'people need'} a follow-up`,'Review new intakes and upcoming check-ins.','Review records','navigate','data-route="care/followups"')}${attentionItem('clipboard',`${services().filter(s=>s.volunteer===UNASSIGNED&&pendingStatus(s)).length} ${services().filter(s=>s.volunteer===UNASSIGNED&&pendingStatus(s)).length===1?'request':'requests'} awaiting volunteers`,'Your nonprofit partners handle placement.','Track requests','navigate','data-route="care/requests"','green')}${attentionItem('layers','Adding several people?','Create profiles and support requests together.','Open batch intake','navigate','data-route="care/batch"','blue')}</div>`;
 return panelHead('Next steps for your team','A little coordination goes a long way.')+`<div class="attention-list">${attentionItem('clipboard',`${pendingVolunteers().length} volunteer ${pendingVolunteers().length===1?'application':'applications'}`,'Review readiness and welcome new people.','Review applications','navigate','data-route="nonprofit/onboarding"')}${attentionItem('building',`${openRequests().length} partner ${openRequests().length===1?'request needs':'requests need'} a volunteer`,'Match skills, language and availability.','Find a match','navigate','data-route="nonprofit/placements"','green')}${attentionItem('clock',`${waitingHours().length} hour submissions to review`,'Recognise the time your volunteers give.','Verify hours','navigate','data-route="nonprofit/hours"','blue')}</div>`;
}
function requestRows(items,care=isCare()){
 return items.map((s,i)=>`<tr><td><button class="row-link" data-action="request" data-id="${esc(s.id)}"><strong>${esc(s.title)}</strong><small>${esc(care?s.beneficiary:facilityName(s.facility))}</small></button></td><td><strong>${s.day+2} Nov · ${s.time}</strong><small>${s.duration} hrs · ${esc(s.language)}</small></td><td>${s.volunteer===UNASSIGNED?'<span class="muted">Awaiting placement</span>':`<span class="person">${personAvatar(s.volunteer,i)}<span>${esc(s.volunteer)}</span></span>`}</td><td>${badge(s.status)}</td><td><button class="text-btn" data-action="request" data-id="${esc(s.id)}" aria-label="View ${esc(s.title)}">${icon('chevron')}</button></td></tr>`).join('');
}
function partnerCard(f){const requests=data.services.filter(s=>s.facility===f.id&&pendingStatus(s));const assigned=requests.filter(s=>s.volunteer!==UNASSIGNED).length;return `<div class="programme-item"><div class="programme-title"><span class="mini-icon">${icon(f.id==='hospital'?'medical':'building')}</span><div><h3>${esc(f.name)}</h3><small>${f.type} · ${f.area}</small></div><span class="percent">${assigned}/${requests.length}</span></div><div class="progress"><span style="width:${requests.length?assigned/requests.length*100:0}%"></span></div><div class="programme-caption"><span>${assigned} volunteer placements</span><span>${requests.length-assigned} open ${requests.length-assigned===1?'request':'requests'}</span></div></div>`}
function coordinationNote(){return `<div class="coordination-note"><span class="coordination-icon">${icon('link')}</span><div><strong>One request. Two teams working together.</strong><p>Care staff describe the support needed. Nonprofits coordinate the volunteers.</p></div><a href="#${isCare()?'nonprofit/placements':'care/requests'}">View as ${isCare()?'nonprofit':'care team'} ${icon('arrow')}</a></div>`}
function queueCards(items,care=false){return `<div class="request-queue">${items.map(s=>`<article class="queue-card"><div class="queue-top">${badge(s.status)}<span>${s.day+2} Nov · ${esc(s.time)}</span></div><h3>${esc(s.title)}</h3><p>${esc(care?s.beneficiary:facilityName(s.facility))} · ${s.duration} hrs</p><div class="queue-bottom"><span>${esc(s.volunteer===UNASSIGNED?s.language:s.volunteer)}</span>${button(care?'Manage request':'Assign volunteer','request','arrow',true,`data-id="${esc(s.id)}"`)}</div></article>`).join('')||'<p class="empty">All current requests have a volunteer.</p>'}</div>`;}
function nonprofitOverview(){return heading('NONPROFIT · VOLUNTEER MANAGEMENT','Your team. Their next good deed.','Manage volunteers, from their first day to their next visit.',button('Assign a volunteer','navigate','heart',true,'data-route="nonprofit/placements"')+button('Add volunteer','new-volunteer','plus'))+`<div class="section-heading"><h2>Requests needing volunteers</h2><a class="text-btn" href="#nonprofit/placements">All requests ${icon('arrow')}</a></div>${queueCards(openRequests().slice(0,2))}<div class="quick-links">${linkRoute('nonprofit/volunteers','Volunteer directory','people')}${linkRoute('nonprofit/onboarding',`${pendingVolunteers().length} ${pendingVolunteers().length===1?'application':'applications'} to review`,'clipboard')}${linkRoute('nonprofit/hours',`${waitingHours().length} hours to verify`,'clock')}<a class="btn" href="../?view=admin#admin">${icon('shield')}Community service approvals</a></div><details class="secondary-content"><summary>Team activity & reports</summary>${nonprofitMetrics()}<div class="dashboard-row"><section class="panel" id="activity">${volunteerChart()}</section><section class="panel">${attention()}</section></div><section class="panel"><div class="programme-list">${data.facilities.map(partnerCard).join('')}</div></section></details>`+coordinationNote();}
function careOverview(){return heading('CARE HOME / HOSPITAL · ELDERLY SUPPORT','Care starts with a helping hand.','Manage residents, patients and the support they need.',button('Request a volunteer','new-request','plus',true)+button(`Add ${residentWord()}`,'new-resident','people'))+facilityBar()+`<div class="quick-links">${linkRoute('care/residents',facility().id==='hospital'?'Patients':'Residents','people')}${linkRoute('care/requests','Service requests','clipboard')}${linkRoute('care/batch','Batch intake','layers')}</div><div class="section-heading"><h2>Upcoming support</h2><a class="text-btn" href="#care/calendar">Schedule ${icon('arrow')}</a></div>${queueCards(services().filter(pendingStatus).slice(0,2),true)}<details class="secondary-content"><summary>Care overview & follow-ups</summary>${careMetrics()}<section class="panel">${attention()}</section></details><div class="quick-links"><a class="btn" href="../?view=institution#services">${icon('calendar')}Community bookings</a><a class="btn" href="../?view=institution#residents">${icon('layers')}Community batch requests</a><a class="btn" href="../?view=elder#explore">${icon('heart')}Open senior view</a></div>`+coordinationNote();}

function toolbar(placeholder,options=['Active','Onboarding']){return `<div class="toolbar"><label class="search-box">${icon('search')}<input data-control="search-list" value="${esc(query)}" placeholder="${placeholder}" aria-label="${placeholder}"></label><select data-control="filter-list" aria-label="Filter records"><option value="all">All statuses</option>${options.map(o=>`<option ${filter===o?'selected':''}>${o}</option>`).join('')}</select></div>`}
function volunteerRows(mode='all'){
 const list=data.volunteers.filter(v=>(mode!=='onboarding'||v.status==='Onboarding')&&(filter==='all'||v.status===filter)&&(v.name+' '+v.skill+' '+v.language).toLowerCase().includes(query.toLowerCase()));
 return list.map((v,i)=>`<tr><td><button class="row-link person" data-action="volunteer" data-id="${esc(v.id)}">${personAvatar(v.name,i)}<span><strong>${esc(v.name)}</strong><small>${esc(v.id)}</small></span></button></td><td><strong>${esc(v.skill)}</strong><small>${esc(v.language)}</small></td><td>${esc(v.availability)}</td><td>${mode==='training'?`${TRAINING.filter(t=>v.training[t]).length} / ${TRAINING.length} completed`:`${v.hours} hrs`}</td><td>${badge(v.status)}</td><td>${textButton(mode==='training'?'Manage training':mode==='onboarding'?'Review':'View','volunteer',`data-id="${esc(v.id)}"`)}</td></tr>`).join('');
}
function volunteersPage(){const mode=page==='onboarding'?'onboarding':page==='training'?'training':'all';const titles={all:['Your volunteer community.','Manage skills, availability and each person’s progress.'],onboarding:['A warm welcome starts here.','Review applications, confirm training and welcome volunteers.'],training:['Help every volunteer feel ready.','Track orientation, conduct and service safety before placement.']};const [title,sub]=titles[mode];return heading('NONPROFIT · PEOPLE & READINESS',title,sub,button('Add volunteer','new-volunteer','plus',true))+`<section class="panel">${toolbar('Search volunteers, languages or skills…')}${table(['Volunteer','Skills / languages','Availability',mode==='training'?'Readiness':'Verified hours','Status',''],volunteerRows(mode))}<div class="panel-foot"><span>${mode==='onboarding'?pendingVolunteers().length:data.volunteers.length} ${mode==='onboarding'?'applications':'volunteers'} in your organisation</span>${textButton('Export volunteers','export','data-kind="volunteers"')}</div></section>${mode==='training'?'<div class="note" style="margin-top:20px">The nonprofit team records completed training and approves volunteers before assigning them to partner requests.</div>':''}`}
function residentRows(){const list=residents().filter(b=>(filter==='all'||b.status===filter)&&(b.name+' '+b.language+' '+b.room+' '+b.programme).toLowerCase().includes(query.toLowerCase()));return list.map((b,i)=>`<tr><td><button class="row-link person" data-action="resident" data-id="${esc(b.id)}">${personAvatar(b.name,i)}<span><strong>${esc(b.name)}</strong><small>${b.age} years · ${esc(b.language)}</small></span></button></td><td><strong>${esc(b.room)}</strong><small>${esc(b.coordinator)}</small></td><td>${esc(b.programme)}</td><td>${badge(b.status)}</td><td><button class="text-btn" data-action="resident" data-id="${esc(b.id)}" aria-label="View ${esc(b.name)}">${icon('chevron')}</button></td></tr>`).join('')}
function residentsPage(){return facilityBar()+heading('CARE INSTITUTION · PEOPLE & NEEDS',facility().id==='hospital'?'Patient records, connected to support.':'Know every resident. Coordinate every visit.','Manage preferences, support needs and service history within your institution.',button('Batch intake','navigate','layers',false,'data-route="care/batch"')+button(`Add ${residentWord()}`,'new-resident','plus',true))+`<section class="panel">${toolbar('Search names, rooms or languages…',['Active','Follow-up due','New intake'])}${table([facility().id==='hospital'?'Patient':'Resident','Room / care coordinator','Support focus','Status',''],residentRows())}<div class="panel-foot"><span>${residents().length} ${residentWord()} profiles · ${esc(facility().name)}</span>${textButton('Export records','export','data-kind="residents"')}</div></section>`}
function requestsPage(){const care=isCare();const list=services().filter(s=>(filter==='all'||s.status===filter)&&(s.title+' '+(care?s.beneficiary:facilityName(s.facility))+' '+s.volunteer).toLowerCase().includes(query.toLowerCase()));return (care?facilityBar():'')+heading(care?'CARE INSTITUTION · SUPPORT REQUESTS':'NONPROFIT · PARTNER REQUESTS',care?'The right support, for each person.':'Find the right volunteer for each request.',care?'Create requests from resident and patient needs. Track volunteer placement and completion.':'Review requests from care homes and hospitals, then match your volunteers.',care?button('New service request','new-request','plus',true):button('View volunteer availability','navigate','people',false,'data-route="nonprofit/volunteers"'))+`<section class="panel">${toolbar(care?'Search services, people or volunteers…':'Search service, care partner or volunteer…',['Needs volunteer','Confirmed','Awaiting verification','Verified'])}${table([care?'Service / person':'Request / care partner','When / language','Volunteer','Status',''],requestRows(list,care))}<div class="panel-foot"><span>${list.length} matching requests</span><span>${care?'Care staff own the support request':'Nonprofits manage volunteer placement'}</span></div></section>`+`<div style="margin-top:20px">${coordinationNote()}</div>`}
function calendarPage(){const care=isCare();return (care?facilityBar():'')+heading(care?'CARE INSTITUTION · VISITS':'NONPROFIT · VOLUNTEER SCHEDULE',care?'A clear picture of the week’s care.':'A week of meaningful placements.',care?'See the people receiving support and the volunteers visiting.':'Coordinate your volunteers across partner institutions.',care?button('Request a visit','new-request','plus',true):button('Assign open requests','navigate','people',true,'data-route="nonprofit/placements"'))+`<section class="panel calendar-panel"><div class="calendar-head"><div><strong>2–8 November 2026</strong><small class="muted" style="display:block;font-size:10px;margin-top:5px">Singapore time · SGT</small></div><div class="segment"><button data-action="calendar-view" data-view="week" class="${!calendarList?'selected':''}">Week</button><button data-action="calendar-view" data-view="list" class="${calendarList?'selected':''}">List</button></div></div><div class="week-grid ${calendarList?'list-view':''}">${DAYS.map((d,i)=>`<div class="day-column ${i===0?'today':''}"><div class="day-name">${d.slice(0,3).toUpperCase()}</div><div class="day-number">${i+2}</div>${services().filter(s=>s.day===i&&s.status!=='Cancelled').sort((a,b)=>a.time.localeCompare(b.time)).map(s=>`<button class="calendar-event ${s.color}" data-action="request" data-id="${esc(s.id)}"><span>${s.time} · ${s.duration} hrs</span><strong>${esc(s.title)}</strong><small>${esc(care?s.beneficiary:facilityName(s.facility))}</small><small>${esc(s.volunteer===UNASSIGNED?'Volunteer needed':s.volunteer)}</small></button>`).join('')}${calendarList&&!services().some(s=>s.day===i)?'<span class="muted" style="font-size:11px">No visits scheduled</span>':''}</div>`).join('')}</div><div class="legend"><span><i class="dot"></i>Companionship</span><span><i class="dot" style="background:#88a3ab"></i>Digital support</span><span><i class="dot" style="background:#bea063"></i>Appointments & errands</span></div></section>`}
function hoursPage(){return heading('NONPROFIT · HOURS & RECOGNITION','Every hour deserves recognition.','Verify submitted service time and track your volunteers’ contribution.',button('Rewards & certificates','navigate','award',false,'data-route="community/rewards"'))+`<div class="metrics three">${metric('Verified hours',totalHours(),'hrs','clock','Across all volunteer profiles','nonprofit/reports')}${metric('Awaiting verification',waitingHours().length,'','clipboard',`${waitingHours().reduce((a,h)=>a+h.hours,0)} submitted hours`,'nonprofit/hours')}${metric('40-hour milestones',data.volunteers.filter(v=>v.hours>=40).length,'','award','Volunteers at or above 40 hours','nonprofit/volunteers')}</div><section class="panel">${panelHead('Service time submissions','Care teams confirm completion. Your nonprofit verifies the hours.')}${table(['Volunteer / service','Care partner','Date','Hours','Status',''],data.hourSubmissions.map(h=>{const v=data.volunteers.find(v=>v.id===h.volunteerId);return `<tr><td><strong>${esc(v?.name||'Volunteer')}</strong><small>${esc(h.title)}</small></td><td>${esc(facilityName(h.facility))}</td><td>${esc(h.date)}</td><td>${h.hours} hrs</td><td>${badge(h.status)}</td><td>${h.status==='Pending'?button('Verify hours','verify-hours','check',false,`data-id="${esc(h.id)}"`):icon('check')}</td></tr>`}).join(''))}<div class="panel-foot"><span>Approved hours are added once to the volunteer’s record.</span>${textButton('Export hours','export','data-kind="hours"')}</div></section><div class="bottom-note" style="margin-top:20px"><div>${icon('award')}<p><strong>Keep the recognition volunteers already know.</strong> Points, rewards, certificates and appeals remain in community tools.</p></div>${linkRoute('community/rewards','Open rewards','arrow')}</div>`}
function followupsPage(){return facilityBar()+heading('CARE INSTITUTION · CONTINUITY','Keep the next step close at hand.','Review new intakes, check in on needs and record the next action.')+`<section class="panel">${panelHead('Follow-up queue',`${followups().length} people need a review.`)}${table(['Person','Needs / preferences','Coordinator','Status',''],followups().map((b,i)=>`<tr><td><button class="row-link person" data-action="resident" data-id="${esc(b.id)}">${personAvatar(b.name,i)}<span><strong>${esc(b.name)}</strong><small>${esc(b.room)}</small></span></button></td><td class="wrap-cell">${esc(b.needs)}</td><td>${esc(b.coordinator)}</td><td>${badge(b.status)}</td><td>${button('Review','resident','arrow',false,`data-id="${esc(b.id)}"`)}</td></tr>`).join(''))}</section>`}
function batchRow(index){return `<tr data-batch-row><td><span class="muted">${index}</span></td><td><input name="batchName" aria-label="Name ${index}" placeholder="Full name" maxlength="70"></td><td><input name="batchAge" aria-label="Age ${index}" type="number" min="1" max="120" placeholder="Age"></td><td><select name="batchLanguage" aria-label="Language ${index}">${['English','Mandarin','Malay','Tamil'].map(l=>`<option>${l}</option>`).join('')}</select></td><td><input name="batchRoom" aria-label="Room or ward ${index}" placeholder="Room / ward" maxlength="60"></td><td><input name="batchNeeds" aria-label="Support needs ${index}" placeholder="Support needs" maxlength="250"></td><td><button type="button" class="icon-btn" data-action="remove-batch-row" aria-label="Remove row">${icon('close')}</button></td></tr>`}
function batchPage(){return facilityBar()+heading('CARE INSTITUTION · BATCH INTAKE','Welcome several people, in one step.','Add up to 30 people to this institution and optionally create individual support requests.')+`<form id="batch-form"><section class="panel">${panelHead(`New ${residentWord()} profiles`,'Fill only the rows you need. Names and ages are required for each completed row.',button('Add row','add-batch-row','plus'))}<div class="table-wrap"><table class="batch-table"><thead><tr><th>#</th><th>Name</th><th>Age</th><th>Language</th><th>Room / ward</th><th>Support needs</th><th></th></tr></thead><tbody id="batch-rows">${[1,2,3].map(batchRow).join('')}</tbody></table></div></section><section class="panel" style="margin-top:20px"><div class="panel-content"><label class="check-line"><input type="checkbox" name="createRequests" data-control="batch-requests"><span><strong>Create an individual volunteer request for each person</strong><small>Requests will appear in the nonprofit partner request queue.</small></span></label><div id="batch-request-options" class="form-grid" hidden>${selectField('Support category','programme',data.programmes.map(p=>p.name))}${selectField('Service day','day',DAYS.map((d,i)=>`${d}, ${i+2} November`))}${field('Start time (SGT)','time','time','09:00')}${field('Duration in hours','duration','number','1.5','min="0.5" max="12" step="0.5"')}</div><label class="check-line"><input type="checkbox" name="authorised" required><span>I am authorised to add these ${residentWord()} profiles and support requests.</span></label><p class="saved-note">Use fictional details in your organisation. Existing profiles are kept.</p><div class="form-actions">${button('Review intake','review-batch','arrow',true,'type="submit"')}</div></div></section></form>`}
function reportsPage(){const care=isCare();const rows=care?data.programmes.map(p=>{const s=services().filter(s=>s.programme===p.name);return [p.name,s.length,s.filter(s=>s.volunteer!==UNASSIGNED).length,s.filter(s=>['Awaiting verification','Verified','Completed'].includes(s.status)).length]}):data.volunteers.map(v=>[v.name,v.status,TRAINING.filter(t=>v.training[t]).length+'/'+TRAINING.length,data.services.filter(s=>s.volunteer===v.name&&pendingStatus(s)).length,v.hours]);return (care?facilityBar():'')+heading(care?'CARE INSTITUTION · SERVICE REPORTS':'NONPROFIT · VOLUNTEER REPORTS',care?'See how support reaches your people.':'See your volunteers’ contribution.',care?'Track service coverage and follow-ups within your institution.':'Review team readiness, placements and verified volunteer hours.',button('Export report','export','download',true,`data-kind="${care?'institution-report':'volunteer-report'}"`))+(care?careMetrics():nonprofitMetrics())+`<section class="panel">${panelHead(care?'Support delivery by category':'Volunteer readiness & contribution',care?'Current requests in this institution.':'Current sample records; approved hours are cumulative.')}${table(care?['Support category','Requests','Assigned','Completed']:['Volunteer','Status','Training','Upcoming placements','Verified hours'],rows.map(r=>`<tr>${r.map((c,i)=>`<td>${i===0?`<strong>${esc(c)}</strong>`:esc(c)}</td>`).join('')}</tr>`).join(''))}<div class="panel-foot"><span>${care?'Resident and patient records stay in the care workspace.':'This report covers volunteer operations.'}</span><span>Fictional demo data</span></div></section>`}
function communityPage(){const [role,p]=LEGACY[page]||LEGACY.volunteer;location.replace(portalURL(role,p));return '<p>Opening Silver Link…</p>';}
function portalURL(role,legacyPage){const u=new URL('../',location.href);u.searchParams.set('view',role);u.hash=legacyPage;return u.href}
function settingsPage(){return (isCare()?facilityBar():'')+heading(isCare()?'CARE INSTITUTION · SETTINGS':'NONPROFIT · SETTINGS','A workspace for your team.','Update the organisation details used in your organisation.')+`<section class="panel settings-layout"><div class="panel-content"><form id="settings-form"><div class="form-grid">${field(isCare()?'Institution name':'Nonprofit name','name','text',isCare()?facility().name:data.org,'required maxlength="70"')}${field('Timezone','timezone','text','Singapore (SGT · UTC+8)','readonly')}</div><label class="toggle-row"><span>Larger text<small>Increase text size in staff views.</small></span><input type="checkbox" name="large" ${data.largeText?'checked':''}></label><div class="form-actions">${button('Save preferences','save-settings','check',true,'type="submit"')}</div></form><div class="section-label">This workspace manages</div><p class="muted" style="font-size:12px">${isCare()?'Resident and patient profiles, support needs, service requests, care schedules and follow-ups.':'Volunteer profiles, recruitment, training, placements, service hours and recognition.'}</p></div></section>`}
function render(){
 document.body.classList.toggle('large-text',!!data.largeText);shell();
 $('#main').className=workspace==='community'?'portal-main':'';
 const view=workspace==='community'?communityPage:page==='overview'?(isCare()?careOverview:nonprofitOverview):['volunteers','onboarding','training'].includes(page)?volunteersPage:page==='residents'?residentsPage:page==='placements'||page==='requests'?requestsPage:page==='shifts'||page==='calendar'?calendarPage:page==='hours'?hoursPage:page==='followups'?followupsPage:page==='batch'?batchPage:page==='reports'?reportsPage:settingsPage;
 $('#main').innerHTML=view();mobileNav();labelTables();document.title=`Silver Link · ${VIEW_NAMES[workspace]} · ${PAGE_LABELS[workspace][page]}`;
}
function showDialog(title,body,drawer=false){const d=$('#dialog');d.className=drawer?'drawer':'';d.innerHTML=`<div class="dialog-header"><h2 id="dialog-title">${title}</h2><button type="button" class="icon-btn" data-action="close" aria-label="Close dialog">${icon('close')}</button></div>${body}`;if(!d.open)d.showModal();}
function field(label,name,type='text',value='',attrs=''){return `<label class="field">${label}<input name="${name}" type="${type}" value="${esc(value)}" ${attrs}></label>`}
function selectField(label,name,options,selected=''){return `<label class="field">${label}<select name="${name}">${options.map(o=>{const value=typeof o==='object'?o.value:o;const label=typeof o==='object'?o.label:o;return `<option value="${esc(value)}" ${value===selected?'selected':''}>${esc(label)}</option>`}).join('')}</select></label>`}
function formActions(label='Save record'){return `<p class="saved-note">Use fictional details. Changes stay in your organisation.</p><div class="form-actions">${button('Cancel','close')}${button(label,'form-submit','check',true,'type="submit"')}</div>`}
function volunteerDetail(id){
 if(workspace!=='nonprofit')return;const v=data.volunteers.find(v=>v.id===id);if(!v)return;
 const ready=TRAINING.every(t=>v.training[t]);
 showDialog('Volunteer profile',`<div class="detail-title">${personAvatar(v.name,1)}<div><h3>${esc(v.name)}</h3><p>${esc(v.skill)} · ${esc(v.language)}</p></div></div>${badge(v.status)}<div class="detail-grid"><div><small>Verified hours</small><strong>${v.hours} hours</strong></div><div><small>Upcoming placements</small><strong>${data.services.filter(s=>s.volunteer===v.name&&pendingStatus(s)).length}</strong></div></div><form id="volunteer-profile-form" data-id="${esc(id)}"><div class="form-grid">${field('Languages','language','text',v.language,'required maxlength="100"')}${selectField('Availability','availability',['Weekdays','Weekends','Flexible'],v.availability)}${selectField('Primary skill','skill',['Befriending','Digital support','Clinic accompaniment','Daily errands'],v.skill)}</div><div class="section-label">Training & readiness</div>${TRAINING.map(t=>`<label class="check-line"><input type="checkbox" name="training" value="${esc(t)}" ${v.training[t]?'checked':''}><span>${t} completed</span></label>`).join('')}<div class="form-actions">${button('Save readiness','save-readiness','check',true,'type="submit"')}</div></form>${v.status==='Onboarding'?`<div class="section-label">Coordinator review</div><p class="muted" style="font-size:12px">${ready?'All required training is recorded. This volunteer is ready for review.':'Record all three training items before approving this volunteer.'}</p>${button('Approve volunteer','approve-volunteer','check',false,`data-id="${esc(id)}" ${ready?'':'disabled'}`)}`:''}<div class="section-label">Recognition</div><p class="muted" style="font-size:12px">${v.hours>=40?'This volunteer has reached the 40-hour milestone.':`${40-v.hours} more verified hours to the 40-hour milestone.`}</p>${linkRoute('community/rewards','Explore existing rewards','award')}`,true);
}
function residentDetail(id){
 if(!isCare())return;const b=residents().find(b=>b.id===id);if(!b)return;
 const history=data.services.filter(s=>s.beneficiaryId===b.id);
 showDialog(facility().id==='hospital'?'Patient profile':'Resident profile',`<div class="detail-title">${personAvatar(b.name,2)}<div><h3>${esc(b.name)}</h3><p>${b.age} years · ${esc(b.language)} · ${esc(b.room)}</p></div></div>${badge(b.status)}<div class="detail-grid"><div><small>Institution</small><strong>${esc(facility().name)}</strong></div><div><small>Care coordinator</small><strong>${esc(b.coordinator)}</strong></div><div><small>Support focus</small><strong>${esc(b.programme)}</strong></div><div><small>Last contact</small><strong>${esc(b.last)}</strong></div></div><div class="section-label">Needs & preferences</div><p class="muted" style="font-size:12px">${esc(b.needs)}</p><div class="actions">${button('Request volunteer support','new-request','heart',true,`data-resident="${esc(id)}"`)}${b.status!=='Active'?button('Mark reviewed','review-resident','check',false,`data-id="${esc(id)}"`):''}</div><div class="section-label">Visits & support history</div><div class="timeline">${history.map(s=>`<p><strong>${esc(s.title)}</strong>${esc(s.volunteer===UNASSIGNED?'Awaiting volunteer placement':s.volunteer)} · ${esc(s.status)}<small>${s.day+2} November · ${s.time} SGT</small></p>`).join('')||'<p>No visits recorded yet.</p>'}</div><div class="section-label">Care team notes</div><div class="timeline">${(data.notes[id]||[]).map(n=>`<p>${esc(n)}<small>Care team follow-up</small></p>`).join('')||'<p>No follow-up notes yet.</p>'}</div><form id="note-form" data-id="${esc(id)}"><label class="field">Add a follow-up note<textarea name="note" maxlength="500" required placeholder="Next steps and support preferences"></textarea></label><div class="form-actions">${button('Save note','save-note','check',true,'type="submit"')}</div></form>`,true);
}
function conflictFor(s,volunteer,ignoreId=s.id){const start=minutes(s.time),end=start+Number(s.duration)*60;return data.services.find(x=>x.id!==ignoreId&&x.day===Number(s.day)&&pendingStatus(x)&&x.volunteer===volunteer&&start<minutes(x.time)+x.duration*60&&end>minutes(x.time));}
const minutes=t=>Number(t.slice(0,2))*60+Number(t.slice(3));
function requestDetail(id){
 const s=services().find(s=>s.id===id);if(!s)return;
 const care=isCare();const b=data.beneficiaries.find(b=>b.id===s.beneficiaryId);
 const available=activeVolunteers().filter(v=>TRAINING.every(t=>v.training[t])&&!conflictFor(s,v.name));
 const selectedVolunteer=available.find(v=>v.name===s.volunteer)?.name||UNASSIGNED;
 let actions='';
 if(!care&&pendingStatus(s))actions=`<div class="section-label">Volunteer placement</div><form id="assignment-form" data-id="${esc(id)}">${selectField('Assign a volunteer','volunteer',[UNASSIGNED,...available.map(v=>v.name)],selectedVolunteer)}<div class="matching-list">${available.slice(0,4).map(v=>`<div><span>${esc(v.name)}</span><small>${v.language.toLowerCase().includes(s.language.toLowerCase())?'Language match':'Check language'} · ${esc(v.skill)}</small></div>`).join('')}</div><p class="saved-note">Volunteers with overlapping placements are excluded. Check their skills and preferred availability before assigning.</p><div class="form-actions">${button('Save placement','save-assignment','check',true,'type="submit"')}</div></form>`;
 if(care&&s.volunteer!==UNASSIGNED&&pendingStatus(s))actions=`<div class="section-label">After the visit</div><form id="completion-form" data-id="${esc(id)}">${field('Confirmed service hours','hours','number',s.duration,'required min="0.5" max="12" step="0.5"')}<p class="saved-note">Confirm completion to send these hours to the nonprofit for verification.</p><div class="form-actions">${button('Confirm visit completed','complete-visit','check',true,'type="submit"')}</div></form>`;
 showDialog(care?'Care support request':'Volunteer placement',`<div class="detail-title"><span class="avatar">${icon(care?'heart':'building')}</span><div><h3>${esc(s.title)}</h3><p>${esc(facilityName(s.facility))}</p></div></div>${badge(s.status)}<div class="detail-grid">${care?`<div><small>${facility().id==='hospital'?'Patient':'Resident'}</small><strong>${esc(s.beneficiary)}</strong></div><div><small>Room / ward</small><strong>${esc(b?.room||'To be arranged')}</strong></div>`:''}<div><small>Date & time</small><strong>${s.day+2} November · ${s.time} SGT</strong></div><div><small>Duration</small><strong>${s.duration} hours</strong></div><div><small>Communication language</small><strong>${esc(s.language)}</strong></div><div><small>Volunteer</small><strong>${esc(s.volunteer===UNASSIGNED?'Awaiting placement':s.volunteer)}</strong></div></div><div class="section-label">Service brief</div><p class="muted" style="font-size:12px">${esc(s.brief)}</p>${actions}${!care?`<div class="note" style="margin-top:20px">Your team coordinates the volunteer. The care institution manages the individual’s profile and care follow-up.</div>`:s.volunteer===UNASSIGNED?`<div class="note" style="margin-top:20px">This request is in the nonprofit’s partner queue. The assigned volunteer will appear here.</div>`:''}`,true);
}
function newForm(kind,attrs={}){
 let title='',fields='';
 if(kind==='volunteer'&&workspace==='nonprofit'){title='Add a volunteer';fields=field('Full name','name','text','','required maxlength="70"')+field('Languages','language','text','English','required maxlength="100"')+selectField('Primary skill','skill',['Befriending','Digital support','Clinic accompaniment','Daily errands'])+selectField('Availability','availability',['Weekdays','Weekends','Flexible']);}
 else if(kind==='resident'&&isCare()){title=`Add a ${residentWord()}`;fields=field('Full name','name','text','','required maxlength="70"')+field('Age','age','number','70','required min="1" max="120"')+selectField('Communication language','language',['English','Mandarin','Malay','Tamil'])+field('Room / ward','room','text','','required maxlength="60"')+selectField('Support focus','programme',data.programmes.map(p=>p.name))+field('Care coordinator','coordinator','text',facility().staff,'required maxlength="70"')+'<label class="field wide">Needs & preferences<textarea name="needs" required maxlength="500"></textarea></label>';}
 else if(kind==='request'&&isCare()){
  if(!residents().length){toast('Add a resident or patient before creating a request.');return}
  title='Request volunteer support';fields=selectField(facility().id==='hospital'?'Patient':'Resident','beneficiaryId',residents().map(b=>({value:b.id,label:b.name})),attrs.resident)+field('Service title','title','text','','required maxlength="80"')+selectField('Support category','programme',data.programmes.map(p=>p.name))+selectField('Day','day',DAYS.map((d,i)=>({value:String(i),label:`${d}, ${i+2} November`})))+field('Start time (SGT)','time','time','09:00','required')+field('Duration in hours','duration','number','1.5','required min="0.5" max="12" step="0.5"')+'<label class="field wide">Service brief for the volunteer<textarea name="brief" required maxlength="500" placeholder="Describe the support needed during this visit"></textarea></label>';
 }else return;
 showDialog(title,`<form id="create-form" data-kind="${kind}"><div class="form-grid">${fields}</div>${kind==='request'?'<div class="note" style="margin-top:18px">The nonprofit partner will assign a volunteer. You can track the placement from this institution’s request list.</div>':''}${formActions(kind==='request'?'Send service request':'Save record')}</form>`);
}
function createRecord(form){
 const o=Object.fromEntries(new FormData(form)),kind=form.dataset.kind;
 if(kind==='volunteer'&&workspace==='nonprofit'){data.volunteers.unshift({...o,id:uid('V'),hours:0,status:'Onboarding',training:Object.fromEntries(TRAINING.map(t=>[t,false]))});save();go('nonprofit/onboarding');toast('Volunteer added to the onboarding queue.');}
 else if(kind==='resident'&&isCare()){data.beneficiaries.unshift({...o,id:uid('B'),age:Number(o.age),facility:facility().id,area:facility().area,status:'New intake',last:'—'});save();go('care/residents');toast(`${facility().id==='hospital'?'Patient':'Resident'} profile added.`);}
 else if(kind==='request'&&isCare()){
  const b=residents().find(b=>b.id===o.beneficiaryId);if(!b)return;
  const s={...o,id:uid('S'),day:Number(o.day),duration:Number(o.duration),beneficiary:b.name,beneficiaryId:b.id,facility:facility().id,language:b.language,volunteer:UNASSIGNED,status:'Needs volunteer',color:data.programmes.find(p=>p.name===o.programme)?.color||''};
  if(minutes(s.time)+s.duration*60>1440){toast('Choose a visit that finishes on the same day.');return}
  if(data.services.some(x=>x.beneficiaryId===b.id&&pendingStatus(x)&&x.day===s.day&&minutes(s.time)<minutes(x.time)+x.duration*60&&minutes(s.time)+s.duration*60>minutes(x.time))){toast('This person already has a visit at that time.');return}
  data.services.push(s);save();go('care/requests');toast('Request sent to the nonprofit volunteer queue.');
 }
}
function reviewBatch(form){
 const rows=[...form.querySelectorAll('[data-batch-row]')].map(row=>Object.fromEntries([...row.querySelectorAll('[name]')].map(el=>[el.name,el.value.trim()]))).filter(r=>r.batchName||r.batchAge||r.batchRoom||r.batchNeeds);
 if(!rows.length){toast('Add at least one person before reviewing.');return}
 if(rows.length>30){toast('Add no more than 30 people at a time.');return}
 if(rows.some(r=>!r.batchName||!r.batchAge||Number(r.batchAge)<1||Number(r.batchAge)>120)){toast('Each completed row needs a name and an age from 1 to 120.');return}
 const common=Object.fromEntries(new FormData(form));
 if(common.createRequests&&(!common.time||Number(common.duration)<.5||Number(common.duration)>12||minutes(common.time)+Number(common.duration)*60>1440)){toast('Enter a valid visit time and duration.');return}
 batchDraft={rows,common,facility:facility().id};
 showDialog('Review batch intake',`<p class="muted" style="font-size:12px">Add ${rows.length} ${residentWord()} profiles to <strong>${esc(facility().name)}</strong>${common.createRequests?` and create ${rows.length} individual volunteer requests`:''}.</p>${table(['Name','Age','Language'],rows.map(r=>`<tr><td>${esc(r.batchName)}</td><td>${r.batchAge}</td><td>${esc(r.batchLanguage)}</td></tr>`).join(''))}<div class="form-actions">${button('Back to edit','close')}${button('Confirm intake','confirm-batch','check',true)}</div>`);
}
function confirmBatch(){if(!isCare()||!batchDraft||batchDraft.facility!==facility().id)return;const {rows,common}=batchDraft;rows.forEach(r=>{const b={id:uid('B'),name:r.batchName,age:Number(r.batchAge),language:r.batchLanguage,room:r.batchRoom||'To be assigned',needs:r.batchNeeds||'Preferences to be confirmed at intake.',programme:common.programme||'Community befriending',coordinator:facility().staff,facility:facility().id,area:facility().area,status:'New intake',last:'—'};data.beneficiaries.push(b);if(common.createRequests)data.services.push({id:uid('S'),title:common.programme,programme:common.programme,beneficiary:b.name,beneficiaryId:b.id,facility:b.facility,language:b.language,day:DAYS.findIndex(d=>common.day.startsWith(d)),time:common.time,duration:Number(common.duration),brief:r.batchNeeds||'Provide companionship and everyday support.',volunteer:UNASSIGNED,status:'Needs volunteer',color:data.programmes.find(p=>p.name===common.programme)?.color||''});});save();batchDraft=null;go('care/residents');toast(`${rows.length} profiles added${common.createRequests?' and support requests sent':''}.`)}
function verifyHours(id){if(workspace!=='nonprofit')return;const h=data.hourSubmissions.find(h=>h.id===id);if(!h||h.status!=='Pending')return;const v=data.volunteers.find(v=>v.id===h.volunteerId);if(!v)return;v.hours=Number(v.hours)+Number(h.hours);h.status='Verified';const s=data.services.find(s=>s.id===h.serviceId);if(s)s.status='Verified';save();render();toast(`${h.hours} verified hours added to ${v.name}’s record.`)}
function search(){showDialog('Search this workspace',`<label class="search-box">${icon('search')}<input id="global-search" aria-label="Search this workspace" placeholder="${isCare()?'Search residents, patients or support requests…':workspace==='nonprofit'?'Search volunteers or partner requests…':'Search community tools…'}" autocomplete="off"></label><div class="search-results" id="search-results"></div>`);searchResults('');$('#global-search').focus()}
function searchResults(q){const rows=workspace==='nonprofit'?[...data.volunteers.map(v=>({id:v.id,title:v.name,sub:'Volunteer',action:'volunteer'})),...data.services.map(s=>({id:s.id,title:s.title,sub:facilityName(s.facility),action:'request'}))]:isCare()?[...residents().map(b=>({id:b.id,title:b.name,sub:b.room,action:'resident'})),...services().map(s=>({id:s.id,title:s.title,sub:s.beneficiary,action:'request'}))]:Object.entries(PAGE_LABELS.community).map(([k,v])=>({id:`community/${k}`,title:v,sub:'Community tool',action:'navigate'}));const matches=rows.filter(r=>(r.title+' '+r.sub).toLowerCase().includes(q.toLowerCase())).slice(0,12);$('#search-results').innerHTML=matches.map(r=>`<button type="button" class="search-result" data-action="${r.action}" ${r.action==='navigate'?`data-route="${r.id}"`:`data-id="${esc(r.id)}"`}><span>${esc(r.title)}</span><small>${esc(r.sub)} ${icon('chevron')}</small></button>`).join('')||'<div class="empty">No matching records in this view.</div>'}
function exportData(kind){
 let rows;
 if(kind==='volunteers'&&workspace==='nonprofit')rows=[['Name','Languages','Skill','Availability','Status','Verified hours'],...data.volunteers.map(v=>[v.name,v.language,v.skill,v.availability,v.status,v.hours])];
 else if(kind==='residents'&&isCare())rows=[['Name','Age','Language','Room / ward','Support focus','Status','Institution'],...residents().map(b=>[b.name,b.age,b.language,b.room,b.programme,b.status,facility().name])];
 else if(kind==='hours'&&workspace==='nonprofit')rows=[['Volunteer','Service','Institution','Date','Hours','Status'],...data.hourSubmissions.map(h=>[data.volunteers.find(v=>v.id===h.volunteerId)?.name,h.title,facilityName(h.facility),h.date,h.hours,h.status])];
 else if(isCare())rows=[['Institution support report — fictional demo data'],['Institution',facility().name],['People supported',residents().length],['Open requests',services().filter(s=>s.volunteer===UNASSIGNED&&pendingStatus(s)).length],['Follow-ups due',followups().length],[],['Service','Resident / patient','Volunteer','Status'],...services().map(s=>[s.title,s.beneficiary,s.volunteer,s.status])];
 else rows=[['Volunteer operations report — fictional demo data'],['Active volunteers',activeVolunteers().length],['Onboarding',pendingVolunteers().length],['Verified volunteer hours',totalHours()],[],['Volunteer','Training completed','Upcoming placements','Verified hours'],...data.volunteers.map(v=>[v.name,TRAINING.filter(t=>v.training[t]).length,data.services.filter(s=>s.volunteer===v.name&&pendingStatus(s)).length,v.hours])];
 const csv='\uFEFF'+rows.map(r=>r.map(x=>'"'+String(x??'').replace(/"/g,'""')+'"').join(',')).join('\r\n');const u=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=u;a.download=`silver-link-${kind}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(u),10000);toast('Records exported.');
}
function refreshDirectory(){const headers=page==='residents'?[facility().id==='hospital'?'Patient':'Resident','Room / care coordinator','Support focus','Status','']:['Volunteer','Skills / languages','Availability',page==='training'?'Readiness':'Verified hours','Status',''];const target=$('#main .table-wrap');if(target)target.outerHTML=table(headers,page==='residents'?residentRows():volunteerRows(page==='onboarding'?'onboarding':page==='training'?'training':'all'));}
document.addEventListener('click',e=>{
 const el=e.target.closest('[data-action]');if(!el)return;const a=el.dataset.action;
 if(a==='navigate')go(el.dataset.route);
 else if(a==='menu')$('#sidebar').classList.toggle('open');
 else if(a==='close')$('#dialog').close();
 else if(a==='facility'&&isCare()){data.selectedFacility=el.dataset.id;query='';filter='all';save();render();}
 else if(a==='chart'){chartMode=el.dataset.mode;$('#activity').innerHTML=volunteerChart();}
 else if(a==='calendar-view'){calendarList=el.dataset.view==='list';render();}
 else if(a==='new-volunteer')newForm('volunteer');
 else if(a==='new-resident')newForm('resident');
 else if(a==='new-request')newForm('request',el.dataset);
 else if(a==='volunteer')volunteerDetail(el.dataset.id);
 else if(a==='resident')residentDetail(el.dataset.id);
 else if(a==='request')requestDetail(el.dataset.id);
 else if(a==='approve-volunteer'&&workspace==='nonprofit'){const v=data.volunteers.find(v=>v.id===el.dataset.id);if(v&&TRAINING.every(t=>v.training[t])){v.status='Active';save();render();volunteerDetail(v.id);toast('Volunteer approved and available for placement.');}}
 else if(a==='review-resident'&&isCare()){const b=residents().find(b=>b.id===el.dataset.id);if(b){b.status='Active';b.last='2 Nov';data.notes[b.id]??=[];data.notes[b.id].push('Care team reviewed support needs and preferences.');save();render();residentDetail(b.id);toast('Follow-up marked as reviewed.');}}
 else if(a==='verify-hours')verifyHours(el.dataset.id);
 else if(a==='search')search();
 else if(a==='notifications')showDialog('Workspace updates',workspace==='community'?'<p class="muted">Your personal notifications are available inside the selected community experience.</p>':attention(),true);
 else if(a==='add-batch-row'){const count=$$('[data-batch-row]').length;if(count>=30){toast('You can add up to 30 people at once.');return}$('#batch-rows').insertAdjacentHTML('beforeend',batchRow(count+1));}
 else if(a==='remove-batch-row'){if($$('[data-batch-row]').length>1)el.closest('tr').remove();else toast('Keep at least one intake row.');}
 else if(a==='confirm-batch')confirmBatch();
 else if(a==='export')exportData(el.dataset.kind);
 else if(a==='portal-fullscreen'){const [r,p]=LEGACY[page];window.open(portalURL(r,p),'_blank','noopener');}
 else if(a==='about')showDialog('Two teams. One connected service.',`<div class="timeline"><p><strong>Nonprofit view</strong>Manage volunteers: recruitment, readiness, placement, service hours and recognition.</p><p><strong>Care home / hospital view</strong>Manage elderly profiles, needs, support requests, care schedules and follow-ups.</p><p><strong>Connected requests</strong>Create a request in the care view, assign a volunteer in the nonprofit view, then confirm the visit and verify hours.</p><p><strong>Community tools</strong>All original service, rewards, certificate, language and accessibility workflows remain available.</p></div><div class="note">Fictional demo data is saved in this browser. Switching views does not sign in to a real account. Staff requests and individual community requests use separate demo records.</div>`);
 else if(a==='legacy-info')showDialog('Your existing Silver Link tools',`<div class="timeline"><p><strong>Services</strong>Requests, matching, bookings, check-in, check-out, confirmation and verification.</p><p><strong>Recognition & support</strong>Hours, ratings, points, rewards, certificates, appeals and safety feedback.</p><p><strong>People & accessibility</strong>Volunteer, senior and institution profiles; batch intake; four languages; large text and supported browser speech.</p></div><div class="note">These original community demonstrations remain available alongside the revised staff views.</div>`);
});
const $$=s=>[...document.querySelectorAll(s)];
document.addEventListener('submit',e=>{
 e.preventDefault();const form=e.target,fd=new FormData(form);
 if(form.id==='create-form')createRecord(form);
 else if(form.id==='batch-form'&&isCare())reviewBatch(form);
 else if(form.id==='note-form'&&isCare()){const b=residents().find(b=>b.id===form.dataset.id);const text=fd.get('note').trim();if(b&&text){data.notes[b.id]??=[];data.notes[b.id].push(text);save();residentDetail(b.id);toast('Care team note saved.');}}
 else if(form.id==='volunteer-profile-form'&&workspace==='nonprofit'){const v=data.volunteers.find(v=>v.id===form.dataset.id);if(v){v.language=fd.get('language').trim();v.availability=fd.get('availability');v.skill=fd.get('skill');v.training=Object.fromEntries(TRAINING.map(t=>[t,fd.getAll('training').includes(t)]));save();render();volunteerDetail(v.id);toast('Volunteer readiness saved.');}}
 else if(form.id==='assignment-form'&&workspace==='nonprofit'){const s=data.services.find(s=>s.id===form.dataset.id),v=fd.get('volunteer');if(s&&pendingStatus(s)){if(v!==UNASSIGNED&&conflictFor(s,v)){toast('This volunteer has an overlapping placement.');return}s.volunteer=v;s.status=v===UNASSIGNED?'Needs volunteer':'Confirmed';save();render();requestDetail(s.id);toast('Placement updated in both staff views.');}}
 else if(form.id==='completion-form'&&isCare()){const s=services().find(s=>s.id===form.dataset.id);if(s&&s.volunteer!==UNASSIGNED&&pendingStatus(s)){const v=data.volunteers.find(v=>v.name===s.volunteer);if(!v){toast('The assigned volunteer profile could not be found.');return}s.status='Awaiting verification';data.hourSubmissions.unshift({id:uid('H'),serviceId:s.id,volunteerId:v.id,facility:s.facility,title:s.title,date:`${s.day+2} Nov 2026`,hours:Number(fd.get('hours')),status:'Pending'});save();render();requestDetail(s.id);toast('Visit completed. Hours sent to the nonprofit for verification.');}}
 else if(form.id==='settings-form'){if(isCare())facility().name=fd.get('name').trim();else data.org=fd.get('name').trim();data.largeText=fd.get('large')==='on';save();render();toast('Workspace preferences saved.');}
});
document.addEventListener('input',e=>{if(e.target.id==='global-search')searchResults(e.target.value);if(e.target.dataset.control==='search-list'){query=e.target.value;if(['requests','placements'].includes(page)){const target=$('#main .table-wrap');const list=services().filter(s=>(filter==='all'||s.status===filter)&&(s.title+' '+(isCare()?s.beneficiary:facilityName(s.facility))+' '+s.volunteer).toLowerCase().includes(query.toLowerCase()));target.outerHTML=table([isCare()?'Service / person':'Request / care partner','When / language','Volunteer','Status',''],requestRows(list));}else refreshDirectory();labelTables();}});
document.addEventListener('change',e=>{if(e.target.dataset.control==='filter-list'){filter=e.target.value;if(['requests','placements'].includes(page)){const value=query;render();query=value;}else refreshDirectory();}if(e.target.dataset.control==='batch-requests')$('#batch-request-options').hidden=!e.target.checked;});
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();search();}});
window.addEventListener('hashchange',()=>{parseRoute();query='';filter='all';if($('#dialog').open)$('#dialog').close();$('#sidebar').classList.remove('open');render();scrollTo(0,0);});
$('#dialog').addEventListener('click',e=>{if(e.target===$('#dialog')){const b=e.target.getBoundingClientRect();if(e.clientX<b.left||e.clientX>b.right||e.clientY<b.top||e.clientY>b.bottom)e.target.close();}});
parseRoute();save();render();

function mobileNav(){const items=isCare()?[['overview','grid','Home'],['requests','clipboard','Requests'],['residents','people','People']]:[['overview','grid','Home'],['placements','heart','Requests'],['volunteers','people','Volunteers']];$('#mobile-nav').innerHTML=items.map(([p,i,l])=>`<a href="#${workspace}/${p}" ${page===p?'aria-current="page"':''}>${icon(i)}<span>${l}</span></a>`).join('')+`<button data-action="menu">${icon('menu')}<span>More</span></button>`;}
function labelTables(){document.querySelectorAll('table').forEach(t=>{const labels=[...t.querySelectorAll('thead th')].map(h=>h.textContent);t.querySelectorAll('tbody tr').forEach(r=>[...r.cells].forEach((c,i)=>c.dataset.label=labels[i]||''));});}
document.addEventListener('change',e=>{if(e.target.id==='perspective'){if(['volunteer','elder'].includes(e.target.value))location.href=portalURL(e.target.value,'explore');else go(e.target.value+'/overview');}});

document.addEventListener('click',e=>{if(!e.target.closest('#sidebar,[data-action="menu"]'))$('#sidebar').classList.remove('open');});
document.addEventListener('keydown',e=>{if(e.key==='Escape')$('#sidebar').classList.remove('open');});
